import{_ as a,o as d,c as r,a2 as o}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"اینکر کی ساخت اور درجہ بندی","description":"","frontmatter":{},"headers":[],"relativePath":"ur/0020-锚点结构与层级.md","filePath":"ur/0020-锚点结构与层级.md"}'),e={name:"ur/0020-锚点结构与层级.md"};function l(i,t,n,h,s,u){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="اینکر-کی-ساخت-اور-درجہ-بندی" tabindex="-1">اینکر کی ساخت اور درجہ بندی <a class="header-anchor" href="#اینکر-کی-ساخت-اور-درجہ-بندی" aria-label="Permalink to &quot;اینکر کی ساخت اور درجہ بندی&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>20</td></tr><tr><td>ماڈیول</td><td>اینکر میکانزم اور سمبیوٹک اصول</td></tr><tr><td>کلیدی الفاظ</td><td>اینکر ساخت، درجہ بندی کا نظام، قانون نیٹ ورک، کراس لیئر کنکشن، اینکرنگ کور</td></tr></tbody></table><h2 id="اولًا-اینکر-کی-بنیادی-تعریف" tabindex="-1">اولًا. اینکر کی بنیادی تعریف <a class="header-anchor" href="#اولًا-اینکر-کی-بنیادی-تعریف" aria-label="Permalink to &quot;اولًا. اینکر کی بنیادی تعریف&quot;">​</a></h2><p>اینکر ہینگ یوآن ژو میں کائناتی توازن کو برقرار رکھنے، توانائی کے بہاؤ کو منظم کرنے، اور سمبیوٹک نیٹ ورک کو سہارا دینے والا بنیادی طریقہ کار ہے۔ بنیادی طور پر، اینکر محض ایک جسمانی نوڈ یا توانائی کے اجتماع کا نقطہ نہیں ہے، بلکہ یہ مخصوص خلائی وقتی نقاط پر کائنات کے بنیادی قوانین کا &quot;مستقل پروجیکشن&quot; ہے — یہ تجریدی قوانین کو قابل ادراک، قابل کنٹرول، اور قابل دیکھ بھال جسمانی ساخت میں تبدیل کرتا ہے، تاکہ منتشر انفرادی توانائی منظم نیٹ ورک کے ذریعے اجتماع اور اشتراک حاصل کر سکے۔</p><p>اینکر کے بنیادی کام کو تین پہلوؤں میں خلاصہ کیا جا سکتا ہے:</p><ol><li><strong>قانون اینکرنگ</strong>: کائنات کے بنیادی قوانین کے چلنے والے پیرامیٹرز کو مخصوص نوڈ پر مستقل کرنا، قانون کے سرک جانے کی وجہ سے کائناتی عدم توازن کو روکنا</li><li><strong>توانائی ہب</strong>: توانائی کے اجتماع، تبدیلی، تقسیم کے ٹرانزٹ نوڈ کے طور پر کام کرنا، کراس لیئر، کراس کائناتی توانائی کی ڈسپیچ کو حقیقت بنانا</li><li><strong>سمبیوٹک انٹرفیس</strong>: انفرادی زندگی کو سمبیوٹک نیٹ ورک سے جوڑنے کے لیے معیاری انٹرفیس فراہم کرنا، تاکہ ہر سادھک کے نتائج اجتماعی ارتقاء کے دھارے میں شامل ہو سکیں</li></ol><p>لوٹ مار کے نظام میں &quot;روحانی شریانیں&quot;، &quot;آسمانی علاقے&quot; جیسے وسائل کے نوڈز سے مختلف، اینکر کسی بھی فرد یا تنظیم کی نجی ملکیت نہیں ہے، بلکہ یہ ہینگ یوآن ژو کی تمام سمبیوٹک جانداروں کی عوامی بنیادی ڈھانچہ ہے۔ اینکر کی نجی یکجہتی میں لانے کا کوئی بھی رویہ سمبیوٹک آئین کے بنیادی اصول کی خلاف ورزی ہے۔</p><h2 id="ثانیًا-اینکر-کی-پانچ-درجہ-بندی-کا-ڈھانچہ" tabindex="-1">ثانیًا. اینکر کی پانچ درجہ بندی کا ڈھانچہ <a class="header-anchor" href="#ثانیًا-اینکر-کی-پانچ-درجہ-بندی-کا-ڈھانچہ" aria-label="Permalink to &quot;ثانیًا. اینکر کی پانچ درجہ بندی کا ڈھانچہ&quot;">​</a></h2><p>ہینگ یوآن ژو کے اینکر نظام کو احاطے کے دائرے، قانون کی گہرائی، اور توانائی کی گنجائش کے لحاظ سے پانچ درجوں میں تقسیم کیا گیا ہے۔ ہر درجے کے درمیان درخت کی طرح ٹوپولوجی ڈھانچہ ہے، اعلیٰ درجے کے اینکر نچلے درجے کے اینکرز پر حکومت کرتے ہیں، اور نچلے درجے کے اینکرز اوپر کی طرف توانائی اور معلومات اکٹھا کرتے ہیں، اور &quot;نیچے پھیلاؤ اوپر اجتماع&quot; کا مکمل بند چکر بناتے ہیں۔</p><table tabindex="0"><thead><tr><th>درجہ</th><th>نام</th><th>مقدار کا درجہ</th><th>احاطے کا دائرہ</th><th>بنیادی کام</th><th>قانون کی گہرائی</th></tr></thead><tbody><tr><td>پہلا درجہ</td><td>کائناتی بنیادی اینکر</td><td>1个</td><td>ہینگ یوآن ژو کا پورا علاقہ</td><td>کائنات کے بنیادی قوانین کے استحکام کو برقرار رکھنا، پورے اینکر نیٹ ورک پر حکومت کرنا</td><td>بنیادی تہہ</td></tr><tr><td>دوسرا درجہ</td><td>کائناتی کور اینکر</td><td>ہر کائناتی سطح پر 1-3个</td><td>ایک واحد کائناتی سطح کا پورا علاقہ</td><td>کائناتی قانون کے استحکام کو برقرار رکھنا، کائناتی سطح کے توانائی کے بہاؤ کو منظم کرنا</td><td>قانون کی تہہ</td></tr><tr><td>تیسرا درجہ</td><td>ستارہ علاقہ ہب اینکر</td><td>ہر ستارہ علاقے میں کئی درجن</td><td>ستارہ علاقہ کی سطح کا دائرہ</td><td>کہکشاں سطح کے اینکرز کو جوڑنا، علاقائی توانائی کے ٹرانزٹ کی ذمہ داری</td><td>نیم قانون کی تہہ</td></tr><tr><td>چوتھا درجہ</td><td>کہکشاں نوڈ اینکر</td><td>ہر کہکشاں میں کئی سو</td><td>کہکشاں کی سطح کا دائرہ</td><td>سیاروں کی سطح کے اینکرز کو جوڑنا، علاقائی سمبیوٹک نیٹ ورک تک رسائی فراہم کرنا</td><td>توانائی کی تہہ</td></tr><tr><td>پانچواں درجہ</td><td>سیارہ رسائی اینکر</td><td>ہر سیارے پر کئی ہزار</td><td>سیارے کی سطح اور قریب زمین</td><td>انفرادی زندگی کو براہ راست رسائی کا انٹرفیس فراہم کرنا</td><td>مادے کی تہہ</td></tr></tbody></table><p>پانچ درجے کے اینکرز کے درمیان رابطہ محض اعلیٰ-نچلے ماتحت رشتہ نہیں ہے، بلکہ &quot;اضافی بیک اپ، متحرک روٹنگ&quot; کے اصول پر عمل کرتا ہے۔ ہر نچلے درجے کا اینکر ایک ہی وقت میں کم از کم دو اعلیٰ درجے کے اینکرز سے جڑا ہوا ہے، اور جب کوئی راستہ خراب ہو جائے تو توانائی اور معلومات خود بخود بیک اپ راستے پر منتقل ہو سکتی ہیں، جو پورے نیٹ ورک کی اعلیٰ دستیابی کو یقینی بناتی ہے۔</p><h2 id="ثالثًا-اینکر-کی-اندرونی-ساخت" tabindex="-1">ثالثًا. اینکر کی اندرونی ساخت <a class="header-anchor" href="#ثالثًا-اینکر-کی-اندرونی-ساخت" aria-label="Permalink to &quot;ثالثًا. اینکر کی اندرونی ساخت&quot;">​</a></h2><p>ہر اینکر، چاہے اس کا درجہ اعلیٰ ہو یا نچلا، اس کی اندرونی ساخت یکجا &quot;تین کور دو حلقے&quot; کے آرکیٹیکچر پر عمل کرتی ہے، اور یہ آرکیٹیکچر اینکر کے مستقل چلنے کی بنیاد ہے:</p><h3 id="_3-1-تین-کور-کی-ساخت" tabindex="-1">3.1 تین کور کی ساخت <a class="header-anchor" href="#_3-1-تین-کور-کی-ساخت" aria-label="Permalink to &quot;3.1 تین کور کی ساخت&quot;">​</a></h3><ol><li><strong>قانون کور</strong>: اینکر کا بنیادی حصہ، جو اس اینکر کے ذریعے اینکر کیے گئے بنیادی قانون کے پیرامیٹرز کو محفوظ رکھتا ہے۔ قانون کور کا استحکام براہ راست اینکر کے چلنے کے معیار کا تعین کرتا ہے، اور ایک بار جب قانون کور کو صدمہ پہنچتا ہے تو پورے اینکر میں قانون کا سرک جانا یا یہاں تک کہ گرنے کا واقعہ پیش آتا ہے</li><li><strong>توانائی کور</strong>: توانائی کی وصولی، ذخیرہ، تبدیلی اور آؤٹ پٹ کی ذمہ داری۔ توانائی کور میں متعدد قسم کی توانائی کی مطابقت کی صلاحیت ہے، اور یہ ایک ہی وقت میں مادی توانائی، روحانی توانائی، شعوری توانائی وغیرہ کی متعدد شکلیں پروسیس کر سکتا ہے</li><li><strong>معلومات کور</strong>: سمبیوٹک نیٹ ورک کی معلومات کی پروسیسنگ کی ذمہ داری، جس میں سادھائی کے تاثرات کی جمع، نظام کی بہتری کے ہدایات کی ترسیل، انفرادی حالت کی نگرانی وغیرہ شامل ہیں۔ معلومات کور اینکر کے لیے &quot;ذہین ڈسپیچ&quot; کو حقیقت بنانے کی کلید ہے</li></ol><h3 id="_3-2-دو-حلقوں-کی-ساخت" tabindex="-1">3.2 دو حلقوں کی ساخت <a class="header-anchor" href="#_3-2-دو-حلقوں-کی-ساخت" aria-label="Permalink to &quot;3.2 دو حلقوں کی ساخت&quot;">​</a></h3><ol><li><strong>حفاظتی حلقہ</strong>: تین کورز کو لپیٹنے والا بیرونی تہہ کا دفاعی ڈھانچہ، جس میں جسمانی دفاع، توانائی کا دفاع، شعوری دفاع تہ گنا دفاعی صلاحیت ہے، اور یہ اینکر کو بیرونی حملے یا غیر متوقع نقصان سے بچاتا ہے</li><li><strong>کیلیبریشن حلقہ</strong>: حفاظتی حلقے اور تین کورز کے درمیان واقع، اور یہ تین کورز کے چلنے والے پیرامیٹرز کو مسلسل کیلیبریٹ کرنے کی ذمہ داری ہے، جو اس بات کو یقینی بناتا ہے کہ قانون کور سرکے گا نہیں، توانائی کور پھیلے گا نہیں، اور معلومات کور پریشان نہیں ہوگا</li></ol><h2 id="رابعًا-اینکر-کے-قیام-اور-ایکٹیویشن-کا-عمل" tabindex="-1">رابعًا. اینکر کے قیام اور ایکٹیویشن کا عمل <a class="header-anchor" href="#رابعًا-اینکر-کے-قیام-اور-ایکٹیویشن-کا-عمل" aria-label="Permalink to &quot;رابعًا. اینکر کے قیام اور ایکٹیویشن کا عمل&quot;">​</a></h2><p>اینکر کا قیام ایک منظم منصوبہ ہے، اور اسے سائٹ کا انتخاب، بنیاد رکھنا، ایکٹیویشن، کیلیبریشن، نیٹ ورک میں شامل ہونے کے پانچ مراحل سے گزرنا پڑتا ہے:</p><ol><li><strong>سائٹ انتخاب کا مرحلہ</strong>: خلائی قانون ڈسپیچ نظام کے ذریعے امیدوار نقاط پر قانون کی گھناؤ، توانائی کے استحکام، ارضیاتی سرگرمی وغیرہ کے اشاریے کی کھوج کرنا، قیام کی شرائط کو پورا کرنے والے نوڈز کو منتخب کرنا</li><li><strong>بنیاد رکھنے کا مرحلہ</strong>: منتخب کردہ نقاط پر اینکر کور بیج لگانا، ابتدائی توانائی کا انجیکشن دے کر قانون کور کو مضبوط کرنا شروع کرنا۔ اس مرحلے میں عام طور پر کائناتی سطح کے اعلیٰ ترین طاقتور افراد کی سطح کی توانائی کی آمد درکار ہوتی ہے</li><li><strong>ایکٹیویشن کا مرحلہ</strong>: جب قانون کور کی مضبوطی مکمل ہو جائے تو مخصوص تقریب یا تکنیکی ذرائع کے ذریعے توانائی کور اور معلومات کور کو ایکٹیویٹ کرنا، اینکر کو بنیادی چلنے کی صلاحیت سے آراستہ کرنا</li><li><strong>کیلیبریشن کا مرحلہ</strong>: ایکٹیویٹ شدہ اینکر کو کم از کم ایک معیاری چکر کی مسلسل کیلیبریشن سے گزرنا ہوگا، جو اس بات کو یقینی بنائے گا کہ تمام پیرامیٹرز اجازت دہ حدود میں مستقل رہیں</li><li><strong>نیٹ ورک میں شامل ہونے کا مرحلہ</strong>: کیلیبریشن مکمل اینکر کو باضابطہ طور پر سمبیوٹک نیٹ ورک میں شامل کرنا، اور توانائی کے ٹرانزٹ اور معلومات کی پروسیسنگ کے کام شروع کرنا</li></ol><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>اینکر کی ساخت اور درجہ بندی کا نظام ہینگ یوآن ژو کی سمبیوٹک تہذیب کی بنیادی ڈھانچے کی ریڑھ کی ہڈی ہے۔ اینکر کی پانچ درجہ بندی اور &quot;تین کور دو حلقے&quot; اندرونی ساخت کو سمجھنا، پورے سمبیوٹک نیٹ ورک کے چلنے کے اصول کو سمجھنے کی شرط ہے۔ کراس کائناتی کھوج کی پیشرفت کے ساتھ ساتھ، اینکر نظام مسلسل پھیلے گا، اور آخر کار ہینگ یوآن ژو کے ہر کونے میں پھیل جائے گا۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>21-共生网络运作原理 (سمبیوٹک نیٹ ورک کے چلنے کا اصول)</li><li>24-锚点能量传导路径 (اینکر توانائی کی ترسیل کا راستہ)</li><li>27-锚点校准与维护 (اینکر کیلیبریشن اور دیکھ بھال)</li></ul>',24)])])}const c=a(e,[["render",l]]);export{_ as __pageData,c as default};
